"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import styles from "../styles/segmented-control.module.css";

export interface SegmentedControlProps {
  /** Segment labels (each label is also its value) */
  options?: string[];
  /** Controlled selected value */
  value?: string;
  /** Initial selected value when uncontrolled */
  defaultValue?: string;
  /** Called with the newly selected value */
  onValueChange?: (value: string) => void;
  /** Accessible name of the control (rendered as a visible caption when showLabel is true) */
  label?: string;
  /** Show the label as a caption above the control */
  showLabel?: boolean;
  /** Size preset */
  size?: "sm" | "md" | "lg";
  /** Thumb style: a raised neutral pill (iOS) or a solid accent pill */
  variant?: "neutral" | "accent";
  /** Accent color used by the accent variant and focus tint */
  accentColor?: string;
  /** Stretch to fill the container width */
  fullWidth?: boolean;
  /** Spring stiffness of the sliding thumb */
  stiffness?: number;
  /** Disable the whole control */
  disabled?: boolean;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_OPTIONS = ["Daily", "Weekly", "Monthly", "Yearly"];

export function SegmentedControl({
  options = DEFAULT_OPTIONS,
  value: valueProp,
  defaultValue,
  onValueChange,
  label = "Billing period",
  showLabel = false,
  size = "md",
  variant = "neutral",
  accentColor = "#6366f1",
  fullWidth = false,
  stiffness = 520,
  disabled = false,
  className = "",
  style,
}: SegmentedControlProps) {
  const reduce = useReducedMotion();
  const id = React.useId();
  const [inner, setInner] = React.useState<string | undefined>(defaultValue ?? options[1] ?? options[0]);
  const controlled = valueProp !== undefined;
  const selected = controlled ? valueProp : inner;
  const refs = React.useRef<Array<HTMLButtonElement | null>>([]);
  const [pressed, setPressed] = React.useState<number | null>(null);

  const selectedIndex = Math.max(0, options.indexOf(selected ?? ""));

  const select = (i: number) => {
    const v = options[i];
    if (v === undefined || disabled) return;
    if (!controlled) setInner(v);
    if (v !== selected) onValueChange?.(v);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>, i: number) => {
    const n = options.length;
    let next = -1;
    if (e.key === "ArrowRight" || e.key === "ArrowDown") next = (i + 1) % n;
    else if (e.key === "ArrowLeft" || e.key === "ArrowUp") next = (i - 1 + n) % n;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = n - 1;
    if (next < 0) return;
    e.preventDefault();
    select(next);
    refs.current[next]?.focus();
  };

  const transition = reduce ? { duration: 0 } : { type: "spring" as const, stiffness: Math.max(50, stiffness), damping: 36, mass: 0.9 };

  return (
    <div
      className={`${styles.root} ${styles[size] ?? ""} ${fullWidth ? styles.full : ""} ${className}`.trim()}
      data-variant={variant}
      style={{ "--mf-sc-accent": accentColor, ...style } as React.CSSProperties}
    >
      {showLabel && label && (
        <span id={`${id}-label`} className={styles.caption}>
          {label}
        </span>
      )}
      <div
        role="radiogroup"
        aria-labelledby={showLabel && label ? `${id}-label` : undefined}
        aria-label={showLabel && label ? undefined : label || "Options"}
        aria-disabled={disabled || undefined}
        className={styles.track}
      >
        {options.map((opt, i) => {
          const active = i === selectedIndex;
          return (
            <button
              key={`${opt}-${i}`}
              ref={(el) => {
                refs.current[i] = el;
              }}
              type="button"
              role="radio"
              aria-checked={active}
              tabIndex={active ? 0 : -1}
              disabled={disabled}
              data-state={active ? "on" : "off"}
              className={styles.segment}
              onClick={() => select(i)}
              onKeyDown={(e) => onKeyDown(e, i)}
              onPointerDown={() => setPressed(i)}
              onPointerUp={() => setPressed(null)}
              onPointerLeave={() => setPressed(null)}
            >
              {active && (
                <motion.span
                  aria-hidden="true"
                  layoutId={`${id}-thumb`}
                  className={styles.thumb}
                  initial={false}
                  animate={{ scale: pressed === i && !reduce ? 0.95 : 1 }}
                  transition={transition}
                />
              )}
              {i > 0 && <span aria-hidden="true" className={styles.divider} data-hidden={active || i - 1 === selectedIndex ? "true" : "false"} />}
              <span className={styles.text}>{opt}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

.root {
  display: inline-flex;
  flex-direction: column;
  gap: 0.5rem;
  color: var(--mf-fg, #f4f4f6);
  font-size: 0.875rem;
  --mf-sc-h: 2.25rem;
  --mf-sc-pad: 0.1875rem;
  --mf-sc-px: 1rem;
}

.full {
  display: flex;
  width: 100%;
}

.sm {
  font-size: 0.8125rem;
  --mf-sc-h: 1.875rem;
  --mf-sc-px: 0.75rem;
}

.lg {
  font-size: 0.9375rem;
  --mf-sc-h: 2.75rem;
  --mf-sc-pad: 0.25rem;
  --mf-sc-px: 1.375rem;
}

.caption {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--mf-muted, #a1a1aa);
}

.track {
  position: relative;
  display: inline-flex;
  align-items: stretch;
  height: var(--mf-sc-h);
  padding: var(--mf-sc-pad);
  box-sizing: border-box;
  border-radius: 0.625rem;
  background-color: var(--mf-surface-raised, #1b1b22);
  box-shadow: inset 0 0 0 1px var(--mf-border, #2e2e38);
}

.full .track {
  display: flex;
}

.track[aria-disabled="true"] {
  opacity: 0.5;
}

.segment {
  position: relative;
  flex: 1 1 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  padding: 0 var(--mf-sc-px);
  border: 0;
  border-radius: 0.5rem;
  background: transparent;
  color: var(--mf-muted, #a1a1aa);
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: color 180ms ease;
}

.segment:hover:not(:disabled) {
  color: var(--mf-fg, #f4f4f6);
}

.segment:disabled {
  cursor: not-allowed;
}

.segment[data-state="on"] {
  color: var(--mf-fg, #f4f4f6);
}

.segment:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 1px;
  z-index: 2;
}

.thumb {
  position: absolute;
  inset: 0;
  border-radius: 0.5rem;
  background-color: var(--mf-surface, #141419);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.25), 0 3px 8px -2px rgba(0, 0, 0, 0.3), inset 0 0 0 1px var(--mf-border, #2e2e38);
}

.root[data-variant="accent"] .thumb {
  background-color: var(--mf-sc-accent, #6366f1);
  box-shadow: 0 2px 10px -2px color-mix(in srgb, var(--mf-sc-accent, #6366f1) 60%, transparent);
}

.root[data-variant="accent"] .segment[data-state="on"] {
  color: #ffffff;
}

.divider {
  position: absolute;
  left: 0;
  top: 25%;
  bottom: 25%;
  width: 1px;
  background-color: var(--mf-border, #2e2e38);
  transition: opacity 180ms ease;
}

.divider[data-hidden="true"] {
  opacity: 0;
}

.text {
  position: relative;
  z-index: 1;
  overflow: hidden;
  text-overflow: ellipsis;
}

@media (prefers-reduced-motion: reduce) {
  .segment,
  .divider {
    transition: none;
  }

  .thumb {
    transform: none !important;
  }
}

