"use client";

import { motion } from "motion/react";
import { useRef, useState } from "react";

const options = ["Daily", "Weekly", "Monthly", "Yearly"];

export function SegmentedControlTailwind() {
  const [value, setValue] = useState("Weekly");
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const onKey = (e: React.KeyboardEvent, i: number) => {
    const d = e.key === "ArrowRight" ? 1 : e.key === "ArrowLeft" ? -1 : 0;
    if (!d) return;
    e.preventDefault();
    const n = (i + d + options.length) % options.length;
    setValue(options[n]);
    refs.current[n]?.focus();
  };
  return (
    <div role="radiogroup" aria-label="Billing period" className="inline-flex h-9 rounded-[10px] bg-zinc-800/80 p-[3px] ring-1 ring-inset ring-zinc-700">
      {options.map((o, i) => (
        <button key={o} ref={(el) => { refs.current[i] = el; }} type="button" role="radio" aria-checked={o === value} tabIndex={o === value ? 0 : -1} onClick={() => setValue(o)} onKeyDown={(e) => onKey(e, i)} className={`relative flex-1 rounded-lg px-4 text-sm font-medium outline-none focus-visible:ring-2 focus-visible:ring-zinc-200 ${o === value ? "text-zinc-100" : "text-zinc-400 hover:text-zinc-100"}`}>
          {o === value && <motion.span layoutId="sc-thumb" className="absolute inset-0 rounded-lg bg-zinc-900 shadow ring-1 ring-inset ring-zinc-700" transition={{ type: "spring", stiffness: 520, damping: 36 }} />}
          <span className="relative">{o}</span>
        </button>
      ))}
    </div>
  );
}
